public abstract class AstronomyKnowledgeFilter<T>
{
    protected AstronomyKnowledgeFilter(IEnumerable<T> values, AstronomyKnowledgeQueryMatchMode matchMode, IComparer<T> comparer, IEqualityComparer<T>? equality = null)
    { if (!Enum.IsDefined(matchMode)) throw new ArgumentOutOfRangeException(nameof(matchMode)); ArgumentNullException.ThrowIfNull(values); var arr = values.Select(v => v ?? throw new ArgumentException("Filter values cannot contain null entries.", nameof(values))).Distinct(equality).OrderBy(v => v, comparer).ToArray(); if (arr.Length == 0) throw new ArgumentException("Filter must contain at least one value.", nameof(values)); Values = Array.AsReadOnly(arr); MatchMode = matchMode; }
    public IReadOnlyList<T> Values { get; }
    public AstronomyKnowledgeQueryMatchMode MatchMode { get; }
}
